import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.O93z6AWZ.js";const m=JSON.parse('{"title":"Topic 3.4 — Heart Failure (Accelerated)","description":"","frontmatter":{"title":"Topic 3.4 — Heart Failure (Accelerated)"},"headers":[],"relativePath":"en/du_an/suy_tim_risk_dxai.md","filePath":"en/du_an/suy_tim_risk_dxai.md"}'),o={name:"en/du_an/suy_tim_risk_dxai.md"};function s(n,t,d,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="topic-3-4-heart-failure-mortality-risk-stratification-from-tabular-data-accelerated-version" tabindex="-1">Topic 3.4: Heart Failure Mortality Risk Stratification from Tabular Data (ACCELERATED version) <a class="header-anchor" href="#topic-3-4-heart-failure-mortality-risk-stratification-from-tabular-data-accelerated-version" aria-label="Permalink to &quot;Topic 3.4: Heart Failure Mortality Risk Stratification from Tabular Data (ACCELERATED version)&quot;">​</a></h1><p><strong>Topic group:</strong> 3. Clinical Tabular Data &amp; EHR · <strong>Status:</strong> ✅ Literature + accelerated workflow complete</p><div class="tip custom-block"><p class="custom-block-title">⚡ The easiest, fastest topic in the entire project bank</p><p>Raw data and the detailed reference solution are kept <strong>Private</strong> on the department&#39;s GitHub (so students complete the work themselves). This page gives you the information you need to get started.</p></div><p>Read the <strong><a href="/hmyt-book/en/course_project">Management Framework &amp; Rubric</a></strong> first.</p><hr><h2 id="_1-problem-statement" tabindex="-1">1. Problem statement <a class="header-anchor" href="#_1-problem-statement" aria-label="Permalink to &quot;1. Problem statement&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Research question</strong></td><td>Which machine-learning model best predicts mortality risk in heart-failure patients from tabular clinical features?</td></tr><tr><td><strong>Input (X)</strong></td><td>13 clinical features (age, ejection fraction, serum creatinine, serum sodium...)</td></tr><tr><td><strong>Output (Y)</strong></td><td>Binary: death / survival (<code>DEATH_EVENT</code>) during the follow-up period</td></tr><tr><td><strong>Dataset</strong></td><td><a href="https://archive.ics.uci.edu/dataset/519/heart+failure+clinical+records" target="_blank" rel="noreferrer">Heart Failure Clinical Records</a> (UCI/Kaggle) — 299 patients, downloadable immediately, no access request needed</td></tr></tbody></table><h2 id="_2-starter-literature-3-papers-—-deliberately-minimal" tabindex="-1">2. Starter literature (3 papers — deliberately minimal) <a class="header-anchor" href="#_2-starter-literature-3-papers-—-deliberately-minimal" aria-label="Permalink to &quot;2. Starter literature (3 papers — deliberately minimal)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Citekey</th><th>Role</th></tr></thead><tbody><tr><td><code>mpanya2021predicting</code> <em>(CONTEXT)</em></td><td>Systematic review of 30 ML studies for heart failure</td></tr><tr><td><code>chicco2020machine</code></td><td><strong>Source paper</strong> — Random Forest, Accuracy 74.0%, MCC 0.384</td></tr><tr><td><code>ishaq2021improving</code></td><td><strong>Target to beat</strong> — same data + SMOTE, Accuracy 92.6%</td></tr></tbody></table><h2 id="_3-accelerated-workflow-—-5-sessions-with-ready-to-run-code" tabindex="-1">3. Accelerated workflow — 5 sessions, with ready-to-run code <a class="header-anchor" href="#_3-accelerated-workflow-—-5-sessions-with-ready-to-run-code" aria-label="Permalink to &quot;3. Accelerated workflow — 5 sessions, with ready-to-run code&quot;">​</a></h2><p>👉 <strong><a href="/hmyt-book/du_an/suy_tim_risk_dxai_lab">See the full Lab Manual</a></strong> — provides the assignment and per-session tasks for students (the reference solution code is kept <strong>Private</strong> on the department&#39;s GitHub so students code it themselves; the Lab Manual itself is currently Vietnamese-only).</p><table tabindex="0"><thead><tr><th style="text-align:center;">Session</th><th>Content</th><th style="text-align:center;">Duration</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td>EDA + patient-level split + normalization</td><td style="text-align:center;">2–3h</td></tr><tr><td style="text-align:center;">2</td><td>Baseline (Logistic Regression + Random Forest)</td><td style="text-align:center;">2–3h</td></tr><tr><td style="text-align:center;">3</td><td>SMOTE + Extra Trees — aiming for the 92.6% mark</td><td style="text-align:center;">2–3h</td></tr><tr><td style="text-align:center;">4</td><td>Mandatory XAI (SHAP) — cross-checking Serum Creatinine/Ejection Fraction</td><td style="text-align:center;">2–3h</td></tr><tr><td style="text-align:center;">5</td><td>Finalize the report</td><td style="text-align:center;">2–3h</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Zero-Hallucination</p><p>Every citation must match a real key in <code>.bib</code> with a DOI verified via the Crossref API.</p></div>',13)])])}const p=e(o,[["render",s]]);export{m as __pageData,p as default};
